WITH filtered_inventory AS (SELECT * FROM inventory WHERE MONTH(last_restock) IN (3, 4, 12)), last_restock_month_summary AS (SELECT DATE_TRUNC('MONTH', last_restock) AS last_restock_month, store_id, MIN(quantity) AS min_quantity, SUM(quantity) AS total_quantity FROM filtered_inventory GROUP BY DATE_TRUNC('MONTH', last_restock), store_id) SELECT last_restock_month, store_id, min_quantity, total_quantity FROM last_restock_month_summary WHERE total_quantity > 480 ORDER BY total_quantity DESC;
